"""Author an ASCII Vietnamese character-name bank with stable DB IDs and CSV export."""
import csv,json,os,re
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'src/data';O.mkdir(exist_ok=True);target=O/'agents-of-the-moon-vietnamese-names.json';assert not target.exists(),'Preserve edited authoring data'
def split(text):return [s.strip() for s in text.split('|') if s.strip()]
