male=split('Bao|Canh|Cuong|Dat|Duc|Dung|Duy|Hieu|Hoang|Hung|Huy|Khai|Khoa|Khoi|Kien|Long|Loc|Nam|Nghia|Phong|Phuc|Quan|Quang|Quoc|Son|Tai|Tan|Thang|Thinh|Trung|Tuan|Tung|Viet|Vinh|Vuong|Anh Dung|Anh Kiet|Anh Tuan|Bao Duy|Bao Long|Bao Phuc|Bao Quoc|Chi Cuong|Chi Dung|Chi Kien|Chi Thanh|Chi Thien|Chi Trung|Chi Viet|Cong Danh|Cong Minh|Cong Thanh|Cong Vinh|Dinh Phong|Duc Anh|Duc Hieu|Duc Huy|Duc Kien|Duc Minh|Duc Phong|Duc Thang|Duc Thinh|Duc Trung|Duc Viet|Duy An|Duy Khang|Duy Khanh|Duy Long|Duy Manh|Duy Nam|Duy Phong|Duy Quang|Duy Thanh|Duy Thinh|Duy Truong|Duy Tung|Hai Dang|Hai Duong|Hai Long|Hai Nam|Hai Phong|Hai Son|Hai Trieu|Huu Duc|Huu Khang|Huu Nghia|Huu Phuc|Huu Thanh|Huu Thien|Huu Tin|Manh Cuong|Manh Hung|Manh Kien|Minh Duc|Minh Hieu|Minh Hoang|Minh Hung|Minh Huy|Minh Khang|Minh Khoi|Minh Long|Minh Phong|Minh Quan|Minh Quang|Minh Tri|Minh Trung|Ngoc Huy|Ngoc Minh|Ngoc Son|Phuc An|Phuc Lam|Phuc Thinh|Quang Duy|Quang Huy|Quang Khai|Quang Minh|Quang Vinh|Quoc Anh|Quoc Bao|Quoc Duy|Quoc Huy|Quoc Khanh|Quoc Phong|Quoc Trung|Thanh Dat|Thanh Long|Thanh Phong|Thanh Son|Thanh Tung|Thien An|Thien Bao|Thien Long|Thien Phuc|Thien Vu|Trong Duc|Trong Hieu|Trong Nghia|Trong Tin|Tuan Anh|Tuan Kiet|Tuan Minh|Tuan Phong|Tuan Vu|Viet Anh|Viet Dung|Viet Hoang|Viet Khang|Viet Long|Viet Phong|Viet Thanh|Viet Thang|Viet Trung')
female=split('Bich|Chi|Dao|Diep|Diem|Duyen|Hanh|Hien|Hoa|Hong|Hue|Huong|Kim|Lan|Lien|Lieu|Loan|Mai|My|Nga|Ngan|Nhi|Nhung|Nu|Oanh|Quynh|Thao|Thu|Thuy|Trang|Tram|Trinh|Truc|Tu|Uyen|Van|Vi|Vy|Yen|Anh Dao|Anh Duong|Anh Thu|Anh Tuyet|Bao Anh|Bao Chau|Bao Ha|Bao Han|Bao Ngoc|Bao Nhi|Bao Tram|Bich Chau|Bich Ha|Bich Hanh|Bich Lien|Bich Ngoc|Bich Phuong|Cam Ha|Cam Hong|Cam Linh|Cam Ly|Cam Nhung|Cam Tu|Dieu Anh|Dieu Ha|Dieu Hien|Dieu Linh|Dieu Thao|Dieu Trang|Gia Han|Gia Linh|Gia Nhi|Ha Anh|Ha Chau|Ha Linh|Ha My|Ha Phuong|Hai Anh|Hai Chau|Hai Ha|Hai Linh|Hai Yen|Hoai An|Hoai Linh|Hoai Phuong|Hoai Thu|Hoang Anh|Hoang Lan|Hoang Mai|Hong Anh|Hong Chau|Hong Ha|Hong Hanh|Hong Lien|Hong Loan|Hong Mai|Hong Ngoc|Hong Nhung|Hong Phuong|Hong Tham|Hong Thao|Hong Van|Huong Giang|Huong Lan|Huong Ly|Khanh An|Khanh Chi|Khanh Ha|Khanh Huyen|Khanh Linh|Khanh Ly|Khanh Ngoc|Khanh Nhu|Khanh Van|Kim Anh|Kim Chi|Kim Ha|Kim Lien|Kim Loan|Kim Ngan|Kim Ngoc|Kim Phuong|Kim Thoa|Kim Uyen|Lan Anh|Lan Chi|Lan Huong|Lan Ngoc|Lan Phuong|Lan Thanh|Le Anh|Le Chi|Le Ha|Le Hang|Le Huyen|Le Quyen|Lien Anh|Minh Anh|Minh Chau|Minh Ha|Minh Hanh|Minh Huyen|Minh Ngoc|Minh Tam|Minh Thu|Minh Trang|My Anh|My Duyen|My Ha|My Hanh|My Huong|My Lan|My Linh|My Ngoc|My Nhan|My Tien|Ngoc Anh|Ngoc Bich|Ngoc Chau|Ngoc Diep|Ngoc Dung|Ngoc Ha|Ngoc Hanh|Ngoc Hien|Ngoc Hoa|Ngoc Hong|Ngoc Hue|Ngoc Huong|Ngoc Khanh|Ngoc Lan|Ngoc Lien|Ngoc Linh|Ngoc Mai|Ngoc Nga|Ngoc Ngan|Ngoc Nhi|Ngoc Phuong|Ngoc Quynh|Ngoc Thao|Ngoc Thu|Ngoc Tram|Ngoc Trinh|Ngoc Uyen|Ngoc Van|Nguyet Anh|Nguyet Ha|Nguyet Lan|Nguyet Linh|Nguyet Mai|Nguyet Nga|Nguyet Thu|Nguyet Van|Phuong Anh|Phuong Chi|Phuong Ha|Phuong Hien|Phuong Lan|Phuong Linh|Phuong Mai|Phuong Nhi|Phuong Thao|Quynh Anh|Quynh Chi|Quynh Ha|Quynh Hoa|Quynh Huong|Quynh Lan|Quynh Lien|Quynh Mai|Quynh Nga|Quynh Nhu|Quynh Trang|Thanh An|Thanh Ha|Thanh Hang|Thanh Hien|Thanh Hoa|Thanh Huong|Thanh Lan|Thanh Mai|Thanh Ngan|Thanh Nha|Thanh Phuong|Thanh Tam|Thanh Thao|Thanh Thu|Thanh Truc|Thanh Van|Thu Anh|Thu Ha|Thu Hang|Thu Hien|Thu Hoa|Thu Huong|Thu Lan|Thu Mai|Thu Ngoc|Thu Phuong|Thu Thao|Thu Trang|Thuy Anh|Thuy Chi|Thuy Duong|Thuy Ha|Thuy Hanh|Thuy Hoa|Thuy Lan|Thuy Linh|Thuy Mai|Thuy Ngoc|Thuy Nhi|Thuy Phuong|Thuy Tien|Thuy Truc|Thuy Van|Tram Anh|Truc Anh|Truc Chi|Truc Ha|Truc Lam|Truc Linh|Truc Mai|Truc Phuong|Tu Anh|Tu Linh|Tu Uyen|Tuyet Anh|Tuyet Hoa|Tuyet Lan|Tuyet Linh|Tuyet Mai|Tuyet Nga|Tuyet Nhi|Tuyet Nhung|Tuyet Trinh|Tuyet Van|Yen Anh|Yen Chi|Yen Ha|Yen Hoa|Yen Linh|Yen Ngoc|Yen Nhi|Yen Phuong')
both=split('An|Anh|Binh|Chau|Giang|Ha|Hai|Khanh|Lam|Linh|Minh|Ngoc|Phuong|Thanh')
both+=sorted((set(male)&set(female))-set(both));male=[x for x in male if x not in both];female=[x for x in female if x not in both]
entries=[]
for offset,kind,gender,values in [(0,'family_name','b',surnames),(1000,'forename','m',male),(2000,'forename','f',female),(3000,'forename','b',both)]:
 assert len(values)==len(set(values)) and len(values)<1000
 for i,text in enumerate(values):
  assert re.fullmatch('[A-Za-z]+(?: [A-Za-z]+)*',text)
  entries.append(dict(id=str(1986120000+offset+i),type=kind,gender=gender,frequency=1,text=text))
stats=dict(surnames=len(surnames),male_given_names=len(male),female_given_names=len(female),unisex_given_names=len(both),records=len(entries),distinct_full_name_combinations=len(surnames)*(len(male)+len(female)+len(both)))
data=dict(schema_version=1,faction='cr_cth_agents_of_the_moon',name_group='names_mc_agents_of_the_moon_vietnamese',language='Vietnamese ASCII',display_order=['family_name','forename'],purpose='Generated ordinary campaign lord/hero names; fixed legendary names are not replaced',provenance='Authored name bank; no game or third-party assets',id_policy='Stable IDs: retain existing IDs; append unused IDs when extending',statistics=stats,examples=['Nguyen Minh Duc','Tran Ngoc Lan','Le Khanh'],entries=entries)
temp=target.with_name(target.name+'.tmp');temp.write_text(json.dumps(data,indent=2)+'\n',encoding='utf8');os.replace(temp,target)
p=O/'agents-of-the-moon-vietnamese-names.csv';temp=p.with_name(p.name+'.tmp')
with temp.open('w',encoding='utf8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['id','type','gender','frequency','text']);w.writeheader();w.writerows(entries)
os.replace(temp,p);print(json.dumps(stats,indent=2))
